import fs from 'node:fs';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {hash,json} from './bounded-source-hash-20261026.mjs';
const stage='F:/VisibleMedicine/staging/20261027-quadriceps-tour',atlas=stage+'/atlas';
const git=(...args)=>execFileSync('git',['--no-replace-objects','-C',atlas,...args],{encoding:'utf8',windowsHide:true,maxBuffer:32e6}).trim();
