const index=json('CURRENT_CHECKPOINT.json');assert.deepEqual(index.activeWork.current.activeExecutionSessions,[]);assert(index.activeWork.current.ownerWslPolicy.keepRunning&&!index.activeWork.current.ownerPreviewPolicy.restartPermitted);
