for(const r of parent.sourceRows)if(!changed.includes(r.path))assert.equal(hash(atlas+'/'+r.path),r.sha256,r.path);
for(const r of parent.publicRows)assert.equal(hash(atlas+'/'+r.path),r.sha256,r.path);
