const playerSteps=json(stage+'/PLAYER_2_STEPS.json');assert.deepEqual(playerSteps.map(s=>[s.args[0],s.exitCode]),[['scripts/test-guided-playback.mjs',0],['scripts/test-regional-tour-player.mjs',0],['scripts/test-whole-body-guided-learning.mjs',1]]);
const playerLog=fs.readFileSync(stage+'/player-2/runner.stdout.log','utf8');assert(playerLog.includes('pass 87')&&playerLog.includes('fail 0'));
for(const name of['player-2','historical-baseline-1']){assert.equal(json(stage+'/'+name+'/RESULT.json').process.exitCode,1);assert(fs.readFileSync(stage+'/'+name+'/runner.stderr.log','utf8').includes('Initial-selection inverse must be unique'));}
assert.equal(execFileSync('git',['-C','F:/VisibleMedicine/staging/20261027-oral-recall-native/atlas','status','--porcelain'],{encoding:'utf8',windowsHide:true}).trim(),'');
const outcomes=JSON.parse(fs.readFileSync(stage+'/tests-3/runner.stdout.log','utf8').split(/\r?\n/).find(s=>s.startsWith('{"passing":true,"baseline"')));
assert.deepEqual([outcomes.newStops,outcomes.participants,outcomes.unchangedPackets,outcomes.unchangedTopics,outcomes.storageCalls],[6,7,1097,9936,0]);
git('add','--',...authored,...generated);git('commit','-m','Add source-bound quadriceps guided tour with protected review revisions');assert.equal(git('status','--porcelain'),'');
const rows=parent.sourceRows.map(r=>({...r,sha256:hash(atlas+'/'+r.path),bytes:fs.statSync(atlas+'/'+r.path).size}));for(const p of added)rows.push({path:p,sha256:hash(atlas+'/'+p),bytes:fs.statSync(atlas+'/'+p).size});rows.sort((a,b)=>a.path.localeCompare(b.path));
