save(stage+'/VERIFICATION_SUMMARY.json',{at:new Date().toISOString(),passingForStatedScope:true,scope:'Six-stop source-bound quadriceps Guided learning tour; existing playback/review regression checks. Draft content, not clinical approval.',source:pin(sf),checks,outcomes,sharedPlayback:{steps:pin(stage+'/PLAYER_2_STEPS.json'),log:pin(stage+'/player-2/runner.stdout.log'),passingRoots:2,regionalPlayerCases:87},resolvedBaselineFailure:{candidate:pin(stage+'/player-2/RESULT.json'),parent:pin(stage+'/historical-baseline-1/RESULT.json'),reason:'Historical whole-body initial-selection fixture mismatch is present in exact clean parent too. Repaired by exact source inverses with every original assertion/fixture retained; current wholebody-2 passes.',wholeSuitePassing:false},priorFailure:{...pin(stage+'/tests-1/RESULT.json'),cause:'New negative test assigned the unchanged leg region to leg structures; corrected fixture to a foreign region. Product source unchanged.'},priorPlayerFailure:{...pin(stage+'/player-1/RESULT.json'),cause:'Closed historical registry fixture rejected the exact additive quadriceps registration. Added a SHA-guarded inverse preserving all prior source and assertions.'},independentReview:pin(stage+'/INDEPENDENT_REVIEW.json'),geometryAndPublicAssetsUnchanged:true,allOtherToursUnchanged:true,noClinicalDecisionsReadOrMigrated:true,clinicalApproval:false,patientSpaceRegistration:false,fullConfiguredTypes:false,stockBuild:false,websiteImported:false,normalPreviewChanged:false});
console.log(JSON.stringify({source:pin(sf),verification:pin(stage+'/VERIFICATION_SUMMARY.json'),head:json(sf).head,outcomes}));
